func resourceDataLossPreventionContentPolicyCreate(d *schema.ResourceData, meta interface{}) error {
	config := meta.(*transport_tpg.Config)
	userAgent, err := tpgresource.GenerateUserAgentString(d, config.UserAgent)
	if err != nil {
		return err
	}

	obj := make(map[string]interface{})
	displayNameProp, err := expandDataLossPreventionContentPolicyDisplayName(d.Get("display_name"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("display_name"); !tpgresource.IsEmptyValue(reflect.ValueOf(displayNameProp)) && (ok || !reflect.DeepEqual(v, displayNameProp)) {
		obj["displayName"] = displayNameProp
	}
	inspectConfigProp, err := expandDataLossPreventionContentPolicyInspectConfig(d.Get("inspect_config"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("inspect_config"); !tpgresource.IsEmptyValue(reflect.ValueOf(inspectConfigProp)) && (ok || !reflect.DeepEqual(v, inspectConfigProp)) {
		obj["inspectConfig"] = inspectConfigProp
	}
	rulesProp, err := expandDataLossPreventionContentPolicyRules(d.Get("rules"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("rules"); !tpgresource.IsEmptyValue(reflect.ValueOf(rulesProp)) && (ok || !reflect.DeepEqual(v, rulesProp)) {
		obj["rules"] = rulesProp
	}
	unsupportedFileTypeProp, err := expandDataLossPreventionContentPolicyUnsupportedFileType(d.Get("unsupported_file_type"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("unsupported_file_type"); !tpgresource.IsEmptyValue(reflect.ValueOf(unsupportedFileTypeProp)) && (ok || !reflect.DeepEqual(v, unsupportedFileTypeProp)) {
		obj["unsupportedFileType"] = unsupportedFileTypeProp
	}
	inputTooLargeProp, err := expandDataLossPreventionContentPolicyInputTooLarge(d.Get("input_too_large"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("input_too_large"); !tpgresource.IsEmptyValue(reflect.ValueOf(inputTooLargeProp)) && (ok || !reflect.DeepEqual(v, inputTooLargeProp)) {
		obj["inputTooLarge"] = inputTooLargeProp
	}
	failedToScanSupportedFileTypeProp, err := expandDataLossPreventionContentPolicyFailedToScanSupportedFileType(d.Get("failed_to_scan_supported_file_type"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("failed_to_scan_supported_file_type"); !tpgresource.IsEmptyValue(reflect.ValueOf(failedToScanSupportedFileTypeProp)) && (ok || !reflect.DeepEqual(v, failedToScanSupportedFileTypeProp)) {
		obj["failedToScanSupportedFileType"] = failedToScanSupportedFileTypeProp
	}
	defaultActionProp, err := expandDataLossPreventionContentPolicyDefaultAction(d.Get("default_action"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("default_action"); !tpgresource.IsEmptyValue(reflect.ValueOf(defaultActionProp)) && (ok || !reflect.DeepEqual(v, defaultActionProp)) {
		obj["defaultAction"] = defaultActionProp
	}
	loggingConfigsProp, err := expandDataLossPreventionContentPolicyLoggingConfigs(d.Get("logging_configs"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("logging_configs"); !tpgresource.IsEmptyValue(reflect.ValueOf(loggingConfigsProp)) && (ok || !reflect.DeepEqual(v, loggingConfigsProp)) {
		obj["loggingConfigs"] = loggingConfigsProp
	}

	obj, err = resourceDataLossPreventionContentPolicyEncoder(d, meta, obj)
	if err != nil {
		return err
	}

	url, err := tpgresource.ReplaceVars(d, config, transport_tpg.BaseUrl(Product, config)+"{{parent}}/contentPolicies")
	if err != nil {
		return err
	}

	log.Printf("[DEBUG] Creating new ContentPolicy: %#v", obj)
	billingProject := ""

	// err == nil indicates that the billing_project value was found
	if bp, err := tpgresource.GetBillingProject(d, config); err == nil {
		billingProject = bp
	}

	headers := make(http.Header)
	res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "POST",
		Project:   billingProject,
		RawURL:    url,
		UserAgent: userAgent,
		Body:      obj,
		Timeout:   d.Timeout(schema.TimeoutCreate),
		Headers:   headers,
	})
	if err != nil {
		return fmt.Errorf("Error creating ContentPolicy: %s", err)
	}
	// Set computed resource properties from create API response so that they're available on the subsequent Read
	// call.
	err = resourceDataLossPreventionContentPolicyPostCreateSetComputedFields(d, meta, res)
	if err != nil {
		return fmt.Errorf("setting computed ID format fields: %w", err)
	}

	// Store the ID now
	id, err := tpgresource.ReplaceVars(d, config, "{{parent}}/contentPolicies/{{name}}")
	if err != nil {
		return fmt.Errorf("Error constructing id: %s", err)
	}
	d.SetId(id)

	log.Printf("[DEBUG] Finished creating ContentPolicy %q: %#v", d.Id(), res)

	identity, err := d.Identity()
	if err == nil && identity != nil {
		if nameValue, ok := d.GetOk("name"); ok && nameValue.(string) != "" {
			if err = identity.Set("name", nameValue.(string)); err != nil {
				return fmt.Errorf("Error setting name: %s", err)
			}
		}
		if parentValue, ok := d.GetOk("parent"); ok && parentValue.(string) != "" {
			if err = identity.Set("parent", parentValue.(string)); err != nil {
				return fmt.Errorf("Error setting parent: %s", err)
			}
		}
	} else {
		log.Printf("[DEBUG] (Create) identity not set: %s", err)
	}

	return resourceDataLossPreventionContentPolicyRead(d, meta)
}

